1	package skilldb
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"strings"
8		"time"
9	
10		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
11		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
12		"github.com/entireio/cli/cmd/entire/cli/insightsdb"
13		"github.com/entireio/cli/cmd/entire/cli/logging"
14		"github.com/entireio/cli/cmd/entire/cli/transcript"
15	
16		"github.com/go-git/go-git/v6"
17	)
18	
19	// cacheVersion is bumped when matching logic changes to force cache invalidation.
20	// v2: added ResolveSkillName fuzzy matching for LLM-extracted signal names.
21	// v3: attribute Skill tool sessions by reading committed transcripts when skill_signals are absent.
22	const cacheVersion = "v3"
23	
24	// resolveSkillName matches an LLM-extracted skill signal name to a discovered skill.
25	// LLM-extracted names often differ from canonical names (e.g. "e2e:triage" for skill "e2e",
26	// "superpowers:writing-plans" for "writing-plans", "cli-e2e-failure-fix" for "e2e").
27	//
28	// Match priority:
29	//  1. Exact match
30	//  2. Signal is a sub-skill: "parent:child" where parent matches a discovered skill
31	//  3. Last segment match: "prefix:name" where name matches a discovered skill
32	//  4. Discovered skill name is contained in the signal name as a word boundary
33	func ResolveSkillName(signalName string, skillMap map[string]SkillRow) (SkillRow, bool) {
34		// 1. Exact match.
35		if skill, ok := skillMap[signalName]; ok {
36			return skill, true
37		}
38	
39		// 2. Sub-skill: signal "e2e:triage" matches discovered "e2e".
40		if idx := strings.IndexByte(signalName, ':'); idx > 0 {
41			parent := signalName[:idx]
42			if skill, ok := skillMap[parent]; ok {
43				return skill, true
44			}
45		}
46	
47		// 3. Last segment: signal "superpowers:writing-plans" matches discovered "writing-plans".
48		if idx := strings.LastIndexByte(signalName, ':'); idx >= 0 && idx < len(signalName)-1 {
49			lastSeg := signalName[idx+1:]
50			if skill, ok := skillMap[lastSeg]; ok {
51				return skill, true
52			}
53		}
54	
55		// 4. Discovered skill name appears as a delimited segment in the signal.
56		// E.g. signal "cli-e2e-failure-fix" contains discovered skill "e2e".
57		// We check word boundaries using "-" and ":" as delimiters.
58		for name, skill := range skillMap {
59			if len(name) < 2 {
60				continue // skip very short names to avoid false positives
61			}
62			// Check if name appears bounded by delimiters or string edges.
63			searchIn := signalName
64			for {
65				idx := strings.Index(searchIn, name)
66				if idx < 0 {
67					break
68				}
69				leftOK := idx == 0 || searchIn[idx-1] == '-' || searchIn[idx-1] == ':'
70				rightEnd := idx + len(name)
71				rightOK := rightEnd == len(searchIn) || searchIn[rightEnd] == '-' || searchIn[rightEnd] == ':'
72				if leftOK && rightOK {
73					return skill, true
74				}
75				searchIn = searchIn[idx+1:]
76			}
77		}
78	
79		return SkillRow{}, false
80	}
81	
82	// PopulateFromInsightsDB populates the skill analytics DB from insightsdb data.
83	// It queries skill_signals and tool_calls to find sessions that used discovered skills.
84	func (sdb *SkillDB) PopulateFromInsightsDB(ctx context.Context, idb *insightsdb.InsightsDB, discoveredSkills []SkillRow, repoRoot string) error {
85		if len(discoveredSkills) == 0 {
86			return nil
87		}
88	
89		// Collect skill names for querying.
90		skillNames := make([]string, len(discoveredSkills))
91		skillMap := make(map[string]SkillRow, len(discoveredSkills))
92		for i, s := range discoveredSkills {
93			skillNames[i] = s.Name
94			skillMap[s.Name] = s
95		}
96	
97		tx, err := sdb.BeginTx(ctx)
98		if err != nil {
99			return fmt.Errorf("begin transaction: %w", err)
100		}
101		defer func() {
102			if err != nil {
103				_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
104			}
105		}()
106	
107		// Track which sessions we've already inserted to avoid duplicates.
108		type sessionKey struct {
109			skillName    string
110			checkpointID string
111			sessionIndex int
112		}
113		inserted := make(map[sessionKey]bool)
114	
115		// Step 1: From skill_signals — sessions with friction for specific skills.
116		// Fetch all signals and resolve names in Go, since LLM-extracted names
117		// often differ from canonical discovered names.
118		signals, err := idb.QueryAllSkillSignals(ctx)
119		if err != nil {
120			return fmt.Errorf("query skill signals: %w", err)
121		}
122	
123		for _, sig := range signals {
124			skill, ok := ResolveSkillName(sig.SkillName, skillMap)
125			if !ok {
126				logging.Debug(ctx, "skill signal name not matched to any discovered skill",
127					"signal_name", sig.SkillName)
128				continue
129			}
130	
131			key := sessionKey{skill.Name, sig.CheckpointID, sig.SessionIndex}
132			if inserted[key] {
133				continue
134			}
135			inserted[key] = true
136	
137			frictionCount := len(sig.Friction)
138			outcome := "success"
139			if frictionCount > 0 {
140				outcome = "friction"
141			}
142	
143			if err = sdb.InsertSessionTx(ctx, tx, SkillSessionRow{
144				SkillName:     skill.Name,
145				SourceAgent:   skill.SourceAgent,
146				CheckpointID:  sig.CheckpointID,
147				SessionIndex:  sig.SessionIndex,
148				SessionID:     sig.SessionID,
149				Agent:         sig.Agent,
150				Model:         sig.Model,
151				Branch:        sig.Branch,
152				CreatedAt:     sig.CreatedAt,
153				TotalTokens:   sig.TotalTokens,
154				TurnCount:     sig.TurnCount,
155				OverallScore:  sig.OverallScore,
156				FrictionCount: frictionCount,
157				Outcome:       outcome,
158			}); err != nil {
159				return fmt.Errorf("insert skill session: %w", err)
160			}
161	
162			// Insert friction items.
163			for _, f := range sig.Friction {
164				if err = sdb.InsertFrictionTx(ctx, tx,
165					skill.Name, skill.SourceAgent,
166					sig.CheckpointID, sig.SessionIndex,
167					f, "",
168				); err != nil {
169					return fmt.Errorf("insert skill friction: %w", err)
170				}
171			}
172	
173			// Insert missing instruction if present.
174			if sig.MissingInstruction != "" {
175				evidence := strings.Join(sig.Friction, "\n")
176				if err = sdb.InsertMissingInstructionTx(ctx, tx,
177					skill.Name, skill.SourceAgent,
178					sig.CheckpointID, sig.SessionIndex,
179					sig.MissingInstruction, evidence,
180				); err != nil {
181					return fmt.Errorf("insert missing instruction: %w", err)
182				}
183			}
184		}
185	
186		// Step 2: From tool_calls — sessions that used the Skill tool (friction-free uses).
187		toolSessions, err := idb.QuerySkillToolCallSessions(ctx)
188		if err != nil {
189			return fmt.Errorf("query skill tool call sessions: %w", err)
190		}
191	
192		var store *checkpoint.GitStore
193		getStore := func() (*checkpoint.GitStore, error) {
194			if store != nil {
195				return store, nil
196			}
197			repo, openErr := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
198			if openErr != nil {
199				return nil, fmt.Errorf("open repository for transcript fallback: %w", openErr)
200			}
201			store = checkpoint.NewGitStore(repo)
202			return store, nil
203		}
204	
205		for _, ts := range toolSessions {
206			var matchedTranscriptSkill bool
207	
208			cpID, cpErr := id.NewCheckpointID(ts.CheckpointID)
209			if cpErr == nil {
210				store, storeErr := getStore()
211				if storeErr != nil {
212					return storeErr
213				}
214	
215				content, readErr := store.ReadSessionContent(ctx, cpID, ts.SessionIndex)
216				if readErr == nil && content != nil && len(content.Transcript) > 0 {
217					invokedSkills, extractErr := extractSkillInvocationsFromTranscript(content.Transcript)
218					if extractErr != nil {
219						return fmt.Errorf("extract skill invocations from transcript for %s/%d: %w",
220							ts.CheckpointID, ts.SessionIndex, extractErr)
221					}
222	
223					for _, invokedSkill := range invokedSkills {
224						skill, ok := ResolveSkillName(invokedSkill, skillMap)
225						if !ok {
226							continue
227						}
228	
229						key := sessionKey{skill.Name, ts.CheckpointID, ts.SessionIndex}
230						if inserted[key] {
231							continue
232						}
233						inserted[key] = true
234						matchedTranscriptSkill = true
235	
236						if err = sdb.InsertSessionTx(ctx, tx, SkillSessionRow{
237							SkillName:    skill.Name,
238							SourceAgent:  skill.SourceAgent,
239							CheckpointID: ts.CheckpointID,
240							SessionIndex: ts.SessionIndex,
241							SessionID:    ts.SessionID,
242							Agent:        ts.Agent,
243							Model:        ts.Model,
244							Branch:       ts.Branch,
245							CreatedAt:    ts.CreatedAt,
246							TotalTokens:  ts.TotalTokens,
247							TurnCount:    ts.TurnCount,
248							OverallScore: ts.OverallScore,
249							Outcome:      "success",
250						}); err != nil {
251							return fmt.Errorf("insert transcript-attributed skill session: %w", err)
252						}
253					}
254				}
255			}
256	
257			if matchedTranscriptSkill {
258				continue
259			}
260	
261			// We can't determine which specific skill was used from tool_calls alone,
262			// so we skip sessions already covered by skill_signals.
263			// These sessions indicate the Skill tool was invoked but we only record
264			// them if there's exactly one discovered skill (unambiguous attribution).
265			if len(discoveredSkills) == 1 {
266				skill := discoveredSkills[0]
267				key := sessionKey{skill.Name, ts.CheckpointID, ts.SessionIndex}
268				if inserted[key] {
269					continue
270				}
271				inserted[key] = true
272	
273				if err = sdb.InsertSessionTx(ctx, tx, SkillSessionRow{
274					SkillName:    skill.Name,
275					SourceAgent:  skill.SourceAgent,
276					CheckpointID: ts.CheckpointID,
277					SessionIndex: ts.SessionIndex,
278					SessionID:    ts.SessionID,
279					Agent:        ts.Agent,
280					Model:        ts.Model,
281					Branch:       ts.Branch,
282					CreatedAt:    ts.CreatedAt,
283					TotalTokens:  ts.TotalTokens,
284					TurnCount:    ts.TurnCount,
285					OverallScore: ts.OverallScore,
286					Outcome:      "success",
287				}); err != nil {
288					return fmt.Errorf("insert tool call session: %w", err)
289				}
290			}
291		}
292	
293		if err = tx.Commit(); err != nil {
294			return fmt.Errorf("commit transaction: %w", err)
295		}
296		return nil
297	}
298	
299	// RefreshFromInsightsDB checks if the cache is stale and repopulates if needed.
300	// Returns true if the cache was refreshed.
301	func (sdb *SkillDB) RefreshFromInsightsDB(ctx context.Context, idb *insightsdb.InsightsDB, discoveredSkills []SkillRow, repoRoot string) (bool, error) {
302		// Check insightsdb branch tip with cache version prefix.
303		// Bumping cacheVersion forces re-population even if the branch tip hasn't changed,
304		// e.g. after fixing the skill name matching logic.
305		currentTip, err := idb.GetBranchTip(ctx)
306		if err != nil {
307			return false, fmt.Errorf("get insightsdb branch tip: %w", err)
308		}
309	
310		versionedTip := cacheVersion + ":" + currentTip
311	
312		cachedTip, err := sdb.GetCacheTip(ctx)
313		if err != nil {
314			return false, fmt.Errorf("get skilldb cache tip: %w", err)
315		}
316	
317		if versionedTip != "" && versionedTip == cachedTip {
318			return false, nil
319		}
320	
321		// Upsert discovered skills.
322		now := time.Now().UTC()
323		for _, skill := range discoveredSkills {
324			if err = sdb.UpsertSkill(ctx, SkillRow{
325				Name:         skill.Name,
326				SourceAgent:  skill.SourceAgent,
327				Path:         skill.Path,
328				Kind:         skill.Kind,
329				DiscoveredAt: now,
330				LastSeenAt:   now,
331			}); err != nil {
332				return false, fmt.Errorf("upsert skill %q: %w", skill.Name, err)
333			}
334		}
335	
336		// Clear existing session data before repopulating.
337		if err = sdb.clearSessionData(ctx); err != nil {
338			return false, fmt.Errorf("clear session data: %w", err)
339		}
340	
341		// Populate from insightsdb.
342		if err = sdb.PopulateFromInsightsDB(ctx, idb, discoveredSkills, repoRoot); err != nil {
343			return false, fmt.Errorf("populate from insightsdb: %w", err)
344		}
345	
346		// Update cache tip with version prefix.
347		if versionedTip != "" {
348			if err = sdb.SetCacheTip(ctx, versionedTip); err != nil {
349				return false, fmt.Errorf("set cache tip: %w", err)
350			}
351		}
352	
353		return true, nil
354	}
355	
356	// clearSessionData removes all rows from session-related tables.
357	func (sdb *SkillDB) clearSessionData(ctx context.Context) error {
358		tables := []string{"skill_sessions", "skill_friction", "skill_missing_instructions"}
359		for _, table := range tables {
360			if _, err := sdb.db.ExecContext(ctx, "DELETE FROM "+table); err != nil { //nolint:gosec // table names are hardcoded
361				return fmt.Errorf("clear %s: %w", table, err)
362			}
363		}
364		return nil
365	}
366	
367	func extractSkillInvocationsFromTranscript(content []byte) ([]string, error) {
368		lines, err := transcript.ParseFromBytes(content)
369		if err != nil {
370			return nil, fmt.Errorf("parse transcript: %w", err)
371		}
372	
373		seen := make(map[string]bool)
374		var skills []string
375	
376		for _, line := range lines {
377			if line.Type != transcript.TypeAssistant {
378				continue
379			}
380	
381			var msg transcript.AssistantMessage
382			if err := json.Unmarshal(line.Message, &msg); err != nil {
383				continue
384			}
385	
386			for _, block := range msg.Content {
387				if block.Type != transcript.ContentTypeToolUse || block.Name != "Skill" {
388					continue
389				}
390	
391				var input transcript.ToolInput
392				if err := json.Unmarshal(block.Input, &input); err != nil {
393					continue
394				}
395	
396				skill := strings.TrimSpace(input.Skill)
397				if skill == "" || seen[skill] {
398					continue
399				}
400	
401				seen[skill] = true
402				skills = append(skills, skill)
403			}
404		}
405	
406		return skills, nil
407	}
