sig, hasFriction := signalsBySession[sk]
frictionCount := 0
outcome := "success"
if hasFriction && len(sig.Friction) > 0 {
    frictionCount = len(sig.Friction)
    outcome = "friction"
}

if err = sdb.InsertSessionTx(ctx, tx, SkillSessionRow{
    SkillName:     skill.Name,
    SourceAgent:   skill.SourceAgent,
    CheckpointID:  ts.CheckpointID,
    SessionIndex:  ts.SessionIndex,
    SessionID:     ts.SessionID,
    Agent:         ts.Agent,
    Model:         ts.Model,
    Branch:        ts.Branch,
    CreatedAt:     ts.CreatedAt,
    TotalTokens:   ts.TotalTokens,
    TurnCount:     ts.TurnCount,
    OverallScore:  ts.OverallScore,
    FrictionCount: frictionCount,
    Outcome:       outcome,
}); err != nil {
    return fmt.Errorf("insert transcript-attributed skill session: %w", err)
}

if hasFriction {
    for _, f := range sig.Friction {
        if err = sdb.InsertFrictionTx(ctx, tx,
            skill.Name, skill.SourceAgent,
            ts.CheckpointID, ts.SessionIndex,
            f, "",
        ); err != nil {
            return fmt.Errorf("insert transcript-attributed skill friction: %w", err)
        }
    }
    if sig.MissingInstruction != "" {
        evidence := strings.Join(sig.Friction, "\n")
        if err = sdb.InsertMissingInstructionTx(ctx, tx,
            skill.Name, skill.SourceAgent,
            ts.CheckpointID, ts.SessionIndex,
            sig.MissingInstruction, evidence,
        ); err != nil {
            return fmt.Errorf("insert transcript-attributed missing instruction: %w", err)
        }
    }
}
```

This second approach (pre-compute before INSERT) is cleaner since it avoids the UPDATE and matches the pattern used in Step 1.

**Change D: Same treatment for the single-skill fallback path (lines 265-291)**

Apply the same friction lookup pattern to the single-skill fallback at lines 273-289. Before the `InsertSessionTx` call, check `signalsBySession` and set outcome/friction_count accordingly, then insert friction items after.

