343	func (m rootModel) View() string {
344		if m.err != nil {
345			return fmt.Sprintf("Error: %v\n\nCheck database paths and try again.", m.err)
346		}
347	
348		if m.screen == screenPicker && len(m.picker.skills) == 0 && m.picker.stats == nil {
349			return "Loading..."
350		}
351	
352		var b strings.Builder
353	
354		if m.screen == screenPicker {
355			b.WriteString(m.picker.view())
356			b.WriteString("\n")
357			hints := "j/k navigate \u00b7 f filter \u00b7 enter select \u00b7 q quit"
358			info := fmt.Sprintf("%d skills", len(m.picker.skills))
359			b.WriteString(renderStatusBar(m.styles, hints, info, m.width))
360			return b.String()
361		}
362	
363		// Dashboard screen
364		skillName := ""
365		if m.selectedSkill != nil {
366			skillName = m.selectedSkill.Name
367		}
368	
369		b.WriteString(renderTabBar(m.styles, m.activeTab, m.width, skillName))
370		b.WriteString("\n")
371	
372		if m.showHelp {
373			b.WriteString(m.renderHelp())
374		} else {
375			switch m.activeTab {
376			case tabStats:
377				b.WriteString(m.statsTab.view())
378			case tabFriction:
379				b.WriteString(m.frictionTab.view())
380			case tabImprove:
381				b.WriteString(m.improveTab.view())
