383		}
384	
385		// Status bar
386		b.WriteString("\n")
387		if m.errFlash != "" {
388			b.WriteString(m.styles.render(m.styles.errorFlash, m.errFlash))
389		} else {
390			hints := m.activeTabHints()
391			info := m.activeTabInfo()
392			b.WriteString(renderStatusBar(m.styles, hints, info, m.width))
393		}
394	
395		return b.String()
